package com.tarapickle.identity.api;
import com.tarapickle.identity.api.IdentityDtos.*; import com.tarapickle.identity.application.*; import io.swagger.v3.oas.annotations.*; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/auth") @RequiredArgsConstructor @Tag(name="Authentication") public class AuthenticationController {private final AuthenticationService auth;private final AccountService accounts;
 @PostMapping("/register") @ResponseStatus(HttpStatus.CREATED) @Operation(operationId="register",summary="Register account",description="Creates a pending player account and queues email verification.") public RegistrationResponse register(@Valid @RequestBody RegisterRequest r,HttpServletRequest q){return auth.register(r,q.getRemoteAddr());}
 @PostMapping("/verify-email") @ResponseStatus(HttpStatus.NO_CONTENT) @Operation(operationId="verifyEmail",summary="Verify email") public void verify(@Valid @RequestBody VerifyRequest r,HttpServletRequest q){auth.verify(r.token(),q.getRemoteAddr());}
 @PostMapping("/resend-verification") @Operation(operationId="resendVerification",summary="Resend verification") public MessageResponse resend(@Valid @RequestBody ResendRequest r){auth.resend(r.email());return generic();}
 @PostMapping("/login") @Operation(operationId="login",summary="Log in") public TokenResponse login(@Valid @RequestBody LoginRequest r,HttpServletRequest q){return auth.login(r,q.getHeader("User-Agent"),q.getRemoteAddr());}
 @PostMapping("/refresh") @Operation(operationId="refreshToken",summary="Rotate refresh token") public TokenResponse refresh(@Valid @RequestBody RefreshRequest r){return auth.refresh(r.refreshToken());}
 @PostMapping("/password/forgot") @Operation(operationId="forgotPassword",summary="Request password reset") public MessageResponse forgot(@Valid @RequestBody ForgotRequest r){auth.forgot(r.email());return generic();}
 @PostMapping("/password/reset") @ResponseStatus(HttpStatus.NO_CONTENT) @Operation(operationId="resetPassword",summary="Reset password") public void reset(@Valid @RequestBody ResetRequest r){auth.reset(r);}
 @PostMapping("/password/change") @ResponseStatus(HttpStatus.NO_CONTENT) @Operation(operationId="changePassword",summary="Change password",security=@io.swagger.v3.oas.annotations.security.SecurityRequirement(name="bearerAuth")) public void change(@org.springframework.security.core.annotation.AuthenticationPrincipal Jwt jwt,@Valid @RequestBody ChangePasswordRequest r){accounts.change(uid(jwt),sid(jwt),r);}
 @PostMapping("/logout") @ResponseStatus(HttpStatus.NO_CONTENT) @Operation(operationId="logout",summary="Log out",security=@io.swagger.v3.oas.annotations.security.SecurityRequirement(name="bearerAuth")) public void logout(@org.springframework.security.core.annotation.AuthenticationPrincipal Jwt jwt){accounts.logout(uid(jwt),sid(jwt));}
 private MessageResponse generic(){return new MessageResponse("If the account is eligible, an email will be sent.");} static java.util.UUID uid(Jwt j){return java.util.UUID.fromString(j.getSubject());} static java.util.UUID sid(Jwt j){return java.util.UUID.fromString(j.getClaimAsString("sid"));}
}
